update_rule.pseudocode:
initialize exposures_today[i] = 0 for all agents i
for each edge (i, j) in adjacency:
  for ordered pair (i -> j):
    if adopted[i] == True and adopted[j] == False:
      bias = 1 + comm_transmission_bias_strength * (degree(i) > degree(j))
      p_send = min(1.0, comm_transmission_prob_base * bias)
      if Bernoulli(p_send) == 1 and exposures_today[j] < comm_max_exposures_per_day:
        exposures_today[j] += 1
for each agent j:
  decay_factor = 0.5 ** (1 / comm_message_half_life_days)
  update exposures_memory_j = decay_factor * exposures_memory_j + exposures_today[j]
emit exposures_today and exposure_rate_daily = mean(exposures_today)
